  const allocated=Math.round(values.reduce((sum,value)=>sum+value,0)*100)/100;
  if(baseTotal>0&&Math.abs(allocated-Math.round(baseTotal*100)/100)>0.009)return toast(`The allocations must total ${fmt(q,baseTotal)} before discount and tax.`);
