  let created=0;if(!commitChange(()=>{const cancelledAt=new Date().toISOString();if(combined){combined.status='Cancelled';combined.cancelledAt=cancelledAt;combined.updated=cancelledAt;}if(noAdvance)oldServiceProformas.forEach(proforma=>{proforma.status='Cancelled';proforma.cancelledAt=cancelledAt;proforma.updated=cancelledAt;});q.billingMode=billingMode;q.serviceBillingAllocations=values.map(value=>Math.round(value*100)/100);if(q.contract)q.contract.billingMode=billingMode;if(billingMode==='service-wise')created=ClientProcessEngine.prepareServiceProformas(db,q,uid,undefined,q.serviceBillingAllocations)},'Enabled separate service billing for '+(q.client?.name||'client')))return;
