  return `<section class="panel"><h2>${esc(q.client?.name||'Client')} · ${esc(q.project||q.number)}</h2><p>${names.map((name,index)=>`<span class="badge ${index===currentStage?'Paid':''}">${index+1}. ${name}</span>`).join(' → ')}</p><h3>Quotation ${esc(q.number)}</h3><div class="actions">${docActions(q)}${q.status==='Draft'?`<button onclick="processMarkSent('${q.id}')">Mark quotation sent</button>`:''}${q.status==='Sent'?`<button onclick="processRecordApproval('${q.id}')">Record quotation approval</button>`:''}</div>${q.status==='Accepted'?'<p>Quotation approval received.</p>':''}${q.status==='Accepted'&&!q.contractConfirmedAt?`<div class="actions"><button class="primary" onclick="processContract('${q.id}')">Set up delivery &amp; billing</button></div><p class="hint">In contract setup, choose a combined project bill or separate service billing. Separate billing can include a 50% advance proforma for each service, or no advance with invoices after completion.</p>`:''}${q.contractConfirmedAt?`<p><b>Contract confirmed</b> · ${esc(q.contract?.acceptedBy||'Client')} · ${esc(q.contract?.startDate||'Start date to be agreed')} · ${q.contract?.deliveryMode==='sequential'?'Services delivered one by one':'Services delivered together'}</p><div class="actions"><button class="primary" onclick="processProject('${q.id}')">${project?'Open project & assign work':'Create project & assign work'}</button></div><p class="hint">A delivery task is created for each quoted service. Assign a team member and mark it complete to enable its invoice.</p>`:''}${serviceBillingSwitch(q)}${['service-wise','service-completion'].includes(q.billingMode)&&q.contractConfirmedAt?serviceBilling(q,project):p&&q.billingMode!=='service-wise'?`<h3>Proforma ${esc(p.number)} · 50% advance ${esc(fmt(p,totals(p).total))}</h3><div class="actions">${docActions(p)}</div>${receiptActions(p)}${stage(q)===5&&!i&&deliveryComplete?`<button class="primary" onclick="processComplete('${q.id}')">Work complete — prepare final invoice</button>`:''}${i?`<h3>Final invoice ${esc(i.number)} · Balance ${esc(fmt(i,totals(i).balance))}</h3><div class="actions">${docActions(i)}</div>${receiptActions({...i,payments:i.payments})}`:''}`:''}${stage(q)===5&&!i&&!deliveryComplete&&!['service-wise','service-completion'].includes(q.billingMode)?'<p class="hint">Complete each service in the project work plan before preparing the final invoice.</p>':''}${!q.contractConfirmedAt&&q.status==='Accepted'&&p?'<p class="hint">A proforma is already linked to this quotation; use the existing project-wide billing flow.</p>':''}</section>`;
